from billing.quote import CURRENCY_EXPONENTS, format_minor, quote_order


def summary(lines, *, currency="USD", discount_bps=0):
    quote = quote_order(lines, currency=currency, discount_bps=discount_bps)
    exponent = CURRENCY_EXPONENTS[quote.currency]
    return format_minor(quote.total_minor, exponent)

def _quantum(exponent: int) -> Decimal:
    return Decimal(1).scaleb(-exponent)


def format_minor(amount_minor: int, exponent: int) -> str:
    """Render integer minor units as an exact decimal string (no float math).

    ``format_minor(1230, 2) == "12.30"`` and ``format_minor(7, 0) == "7"``.
    """

    if exponent <= 0:
        return str(amount_minor)
    sign = "-" if amount_minor < 0 else ""
    magnitude = abs(amount_minor)
    scale = 10**exponent
    return f"{sign}{magnitude // scale}.{magnitude % scale:0{exponent}d}"

def test_legacy_consumers():
    """The documented consumer output formats are unchanged by the migration."""

    lines = [{"unit_price": "0.10", "quantity": 3}]
